contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 amount, address adr) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint256 beforeBal = address(c).balance;

        c.multiplicate{value: amount}(adr); if (__ESBMC_reverted()) return;

        uint256 afterBal = address(c).balance;

        assert(afterBal == beforeBal || afterBal == beforeBal + amount);
    }
}

